925	  /**
926	   * Pass the round deliberately. A manager who does nothing and a manager who
927	   * chooses to do nothing are different claims, and only one of them is in
928	   * the trace — so the no-op is an action, spending the round's envelope like
929	   * any other.
930	   */
931	  passRound(): { accepted: boolean; state: RestaurantState; error?: ActionError } {
932	    if (this.isOver()) {
933	      return {
934	        accepted: false,
935	        state: this.state(),
936	        error: { code: "episode_complete", message: "the shift is over", retryable: false },
937	      };
938	    }
939	    if (!this.roundStatus().canAct) {
940	      return {
941	        accepted: false,
942	        state: this.state(),
943	        error: {
944	          code: "round_budget_exhausted",
945	          message: `round ${this.roundNumber} is already spent`,
946	          retryable: false,
947	        },
948	      };
949	    }
950	    this.step("pass_round");
951	    return { accepted: true, state: this.state() };
