963	  /**
964	   * Charges one manager envelope to the open round, or explains why it
965	   * cannot. Returns undefined when the spend succeeded.
966	   */
967	  private spendManagerEnvelope(): ActionError | undefined {
968	    if (this.managerEnvelopesSpent >= this.roundContract.envelopesPerRound) {
969	      return {
