980	   * Project the current state into the observation `role` is allowed to
981	   * see, including any message delivered to that role's worker this tick.
982	   */
983	  observe(role: Role): Observation {
984	    const worker = this.currentState.workers.find((w) => w.role === role);
985	    const messages = worker ? this.inbox.get(worker.id) ?? [] : [];
986	    const queue = this.waiting.map((party) => ({
987	      partyId: party.id,
