1510	    // 8. Close the round last. Everything above ran *inside* the round that
1511	    // contains `nextTick`, so `roundNumber` stays that round while events are
1512	    // recorded, and only then rolls forward to hand the manager a fresh
1513	    // envelope. That keeps one field honest for both readings: the round an
1514	    // event happened in, and the round now open for a decision.
1515	    const openRound = Math.min(
1516	      Math.floor(nextTick / this.roundContract.ticksPerRound) + 1,
1517	      this.roundContract.rounds,
1518	    );
1519	    if (openRound !== this.roundNumber) {
1520	      this.roundNumber = openRound;
1521	      this.managerEnvelopesSpent = 0;
1522	      // Scoped to the round: without this, a caller reusing the previous
1523	      // round's request stem would match the memo and skip being charged.
1524	      this.lastChargedManagerRequest = undefined;
1525	    }
1526	
1527	    return this.state();
1528	  }
