1530	  /**
1531	   * The front of house. Parties arrive on a seeded cadence, burn patience
1532	   * while they wait, and either get a table (which puts a real ticket on the
1533	   * board) or walk — which is what makes an idle floor cost something.
1534	   */
1535	  private runDoor(tick: number): void {
1536	    // Arrivals, until the kitchen would have no time left to cook them.
1537	    if (tick >= this.nextArrivalTick && tick < this.currentState.episode.maxTicks - 3) {
1538	      const size = 2 + this.rng.int(3);
1539	      this.partyCounter += 1;
1540	      this.waiting.push({ id: `party-${this.partyCounter}`, size, patience: 1, waitedTicks: 0 });
1541	      const [gapMin, gapSpread] = this.preset.arrivalGap;
1542	      this.nextArrivalTick = tick + gapMin + this.rng.int(gapSpread);
1543	      this.log("house", "event", `A party of ${size} is at the door.`);
1544	    }
1545	
1546	    const host = this.currentState.workers.find((w) => w.role === "host");
1547	    const hostOnDoor = host?.location === "queue" || host?.location === "floor";
1548	
1549	    // Seating: one party per tick, and only with a table free.
1550	    if (!this.externalRoles.has("host") && !this.currentState.seatingHeld && hostOnDoor && this.waiting.length > 0) {
1551	      const table = this.currentState.tables.find((t) => t.status === "empty");
1552	      const party = this.waiting[0];
1553	      if (table && party) {
1554	        this.waiting.shift();
1555	        table.status = "occupied";
1556	        const order = this.createOrder(table.id);
1557	        table.orderId = order.id;
1558	        host.load = Math.min(1, host.load + 0.15);
1559	        host.lastAction = `seat:${table.id}`;
1560	        this.log("host", "action", `Sat the party of ${party.size} at ${table.id.replace("table-", "table ")}.`);
1561	        if (order.allergy) {
1562	          this.log("server", "thought", `${order.allergy} allergy on ${table.id.replace("table-", "table ")}. Flagging it to the pass.`);
1563	        }
1564	      }
1565	    }
1566	
1567	    // Patience, and the walkouts that follow it.
1568	    const decay = (hostOnDoor ? PATIENCE_DECAY_HOSTED : PATIENCE_DECAY) * (this.seatAllPressure ? 1.4 : 1);
1569	    const stayed: WaitingParty[] = [];
1570	    for (const party of this.waiting) {
1571	      const patience = party.patience - decay;
1572	      if (patience > 0) {
1573	        stayed.push({ ...party, patience, waitedTicks: party.waitedTicks + 1 });
1574	        continue;
1575	      }
1576	      this.walkouts += 1;
1577	      this.log("house", "event", `The party of ${party.size} gave up and left.`);
1578	      // A held door is an honest wait — you lose the cover, not the room's
1579	      // opinion of you.
1580	      if (!this.currentState.seatingHeld) {
1581	        this.currentState.reputation = Math.max(0, this.currentState.reputation - 2);
1582	        this.currentState.outcomes.satisfaction = Math.max(0, this.currentState.outcomes.satisfaction - 0.04);
1583	      }
1584	    }
1585	    this.waiting = stayed;
1586	  }
