1592	    // keep the seeded 1-in-N draw so the constraint stays rare enough to price.
1593	    const allergy =
1594	      this.preset.id === TUTORIAL_SHIFT_ID
1595	        ? this.orderCounter === 1
1596	          ? "peanut"
1597	          : undefined
1598	        : this.rng.int(this.preset.allergyOdds) === 0
1599	          ? "peanut"
1600	          : undefined;
