1749	  /**
1750	   * Submit an action envelope, recording the call's telemetry alongside it.
1751	   *
1752	   * Rejections are journalled here rather than inside the validation body, so
1753	   * every refusal path — present and future — reaches the trace as an event
1754	   * with `toolResult.ok === false`. A trace that only carried accepted actions
1755	   * would let a model that failed half its turns read as a clean run.
1756	   */
1757	  stepEnvelope(
1758	    rawEnvelope: ActionEnvelope,
1759	    telemetry?: EnvelopeTelemetry,
1760	  ): { accepted: boolean; state: RestaurantState; error?: ActionError } {
1761	    const envelope = this.adaptLegacyActionEnvelope(rawEnvelope);
1762	    return this.recordInput({ kind: "envelope", envelope, ...(telemetry ? { telemetry } : {}) }, () => this.applyRecordedEnvelope(envelope, telemetry));
1763	  }
1764	
1765	  private applyRecordedEnvelope(envelope: ActionEnvelope, telemetry?: EnvelopeTelemetry) {
1766	    const cached = this.idempotencyCache.get(envelope.idempotencyKey);
1767	    if (cached) return cached;
1768	
1769	    // The manager's round budget is enforced here rather than in
1770	    // submitPlayerIntervention because this is the boundary a replay crosses:
1771	    // replay re-applies recorded envelopes directly, so a check made further
1772	    // up would be missing on the way back through and the two runs would
1773	    // diverge on the first envelope the budget refused. It also means a
1774	    // direct stepEnvelope() caller cannot walk around the budget.
1775	    //
1776	    // `undefined` means this envelope draws on no budget at all: a worker's
1777	    // own action, or a manager answering a raised decision.
1778	    const managerKey =
1779	      envelope.actorType === "player" && envelope.tool !== "approve"
1780	        ? this.managerRequestKey(envelope.requestId)
1781	        : undefined;
1782	    // One instruction to the whole floor arrives as four envelopes sharing a
1783	    // request stem. The first is charged; the rest are the same exercise of
1784	    // authority and neither charge nor re-check.
1785	    const alreadyCharged = managerKey !== undefined && managerKey === this.lastChargedManagerRequest;
1786	
1787	    if (managerKey !== undefined && !alreadyCharged && !this.roundStatus().canAct) {
1788	      const error: ActionError = {
1789	        code: "round_budget_exhausted",
1790	        message: `round ${this.roundNumber} already spent its manager envelope; wait for round ${this.roundNumber + 1}`,
1791	        retryable: false,
1792	      };
1793	      this.journalRejectedEnvelope(envelope, error, telemetry);
1794	      return { accepted: false, state: this.state(), error };
1795	    }
1796	
1797	    this.pendingTelemetry = telemetry;
1798	    try {
1799	      const result = this.applyEnvelope(envelope);
1800	      if (!result.accepted && result.error) {
1801	        this.journalRejectedEnvelope(envelope, result.error, telemetry);
1802	        return result;
1803	      }
1804	      // Charged only once the action actually landed. A ticket that turned out
1805	      // to be cancelled, or an order id that matches nothing, costs the manager
1806	      // nothing — they did not get to change anything with it.
1807	      if (managerKey !== undefined && !alreadyCharged) {
1808	        this.lastChargedManagerRequest = managerKey;
1809	        this.spendManagerEnvelope();
1810	      }
1811	      return result;
1812	    } finally {
1813	      this.pendingTelemetry = undefined;
1814	    }
1815	  }
