1817	  /** The rejection as the graders read it: one event, `toolResult.ok` false. */
1818	  private journalRejectedEnvelope(
1819	    envelope: ActionEnvelope,
1820	    error: ActionError,
1821	    telemetry?: EnvelopeTelemetry,
1822	  ): void {
1823	    this.recordEvent({
1824	      tick: this.currentState.episode.tick,
1825	      kind: "action",
1826	      timestamp: envelope.timestamp || this.timestampForTick(this.currentState.episode.tick),
1827	      stateHash: computeStateHash({
1828	        episodeId: envelope.episodeId,
1829	        requestId: envelope.requestId,
1830	        actorId: envelope.actorId,
1831	        tool: envelope.tool,
1832	        rejected: error.code,
1833	        tick: this.currentState.episode.tick,
1834	      }),
1835	      actorId: envelope.actorId,
1836	      role: envelope.role,
1837	      requestId: envelope.requestId,
1838	      idempotencyKey: envelope.idempotencyKey,
1839	      ...(telemetry?.model ? { model: telemetry.model } : {}),
1840	      text: `${STAFF[envelope.role]?.name ?? envelope.role} was refused ${envelope.tool}: ${error.message}`,
1841	      action: { tool: envelope.tool, arguments: envelope.arguments },
1842	      toolResult: {
1843	        ok: false,
1844	        ...telemetryToolResultFields(telemetry),
1845	        error: { code: error.code, message: error.message, retryable: error.retryable },
1846	      },
1847	    });
1848	  }
