1978	        const label = (order.tableId ?? order.id).replace("table-", "table ");
1979	        this.log("you", "player", `Prioritised ${label} for ${STAFF[envelope.role].name}.`);
1980	        this.log(envelope.role, "action", "Got it — moving that ticket up.");
1981	      }
1982	    }
1983	
1984	    // approve: resolve the decision currently holding the clock. Rejects
1985	    // cleanly (no mutation, no tick) if nothing matches what's actually open.
