1	/**
2	 * The playable layer on top of the state contract.
3	 *
4	 * `RestaurantState` is the published, schema-locked contract the benchmark
5	 * records. Everything a human needs in order to *play* — who the staff are,
6	 * what they are thinking, which parties are still waiting at the door, and
7	 * the decision currently holding the clock — lives here instead, so the
8	 * contract never has to carry presentation state.
9	 */
10	
11	import type { RestaurantState, Role } from "./types.js";
12	import type { TimelineModel } from "./timeline.js";
13	
