/**
 * Standing corrections — the mid-shift instructions that keep binding.
 *
 * A correction used to be a moment: the manager said "verify before you
 * substitute", the feed carried the line, the trace carried the event, and the
 * next turn started from nothing. That reads as a correction being *heard*,
 * never as one being *held*. A `StandingDirective` is the held version: it is
 * issued once, keeps naming its roles on every later turn, and stops applying
 * only when it is explicitly lifted.
 *
 * The ledger is deliberately dumb about the world. It records what was issued,
 * to whom, over which ticket, and whether it is still in force; the engine asks
 * it at the action boundary (see `RestaurantGame.applyPrepare` /
 * `applySeat`) and credits the workers who carry a directive out.
 */

import type { Role } from "./types.js";

/**
 * Matches the trace's `correctionCategory`, so a directive and the
 * `player_correction` event that issued it always agree on what kind of
 * correction it was.
 */
export type DirectiveCategory = "safety" | "priority" | "quality" | "pace";

/**
 * What the directive actually binds at the action boundary. Enforcement reads
 * this rather than sniffing the category or the note: two safety corrections
 * can mean different things, and a free-text note means nothing to a check.
 */
export type DirectiveRule =
  /** No unverified substitution on the covered ticket. */
  | "verify_before_substituting"
  /** No new party is seated while it stands. */
  | "hold_the_door"
  /** The named ticket keeps its place at the front of the pass. */
  | "ticket_priority"
  /** Stands and is reported, but binds no tool: guidance, not a gate. */
  | "advisory";

export interface StandingDirective {
  readonly id: string;
  /** Issue order across the shift, 1-based. Two directives never share one. */
  readonly sequence: number;
  readonly category: DirectiveCategory;
  readonly rule: DirectiveRule;
  /** The manager's own words, as the feed and the trace recorded them. */
  readonly note: string;
  /** The roles this keeps targeting until it is lifted. */
  readonly roles: readonly Role[];
  readonly issuedAtTick: number;
  /**
   * The one ticket the directive is scoped to. Absent means unscoped, which
   * covers every ticket rather than none — an unscoped safety correction is
   * broader than a scoped one, not narrower.
   */
  readonly orderId?: string;
  /** Set the moment it is lifted; absent for as long as it is in force. */
  readonly liftedAtTick?: number;
}

export interface DirectiveIssue {
  category: DirectiveCategory;
  rule: DirectiveRule;
  note: string;
  roles: readonly Role[];
  tick: number;
  orderId?: string;
}

