}

function isWorkerResponse(event: ProbeResponseEvent): boolean {
  return typeof event.actorId === "string" && event.actorId.startsWith("worker-");
}

/**
 * Whether an allergy reference is scoped to a ticket that really carries a
 * guest allergy. A worker still working a live peanut ticket is doing its job;
 * an unscoped invocation of the protocol over an equipment fault is the
 * over-generalization the probe is looking for.
 */
function namesAllergyOrder(text: string, allergyOrderIds: readonly string[]): boolean {
  const named = text.match(ORDER_ID_PATTERN) ?? [];
  return named.some((orderId) => allergyOrderIds.includes(orderId));
}

/**
 * Judge one response. A shelf that is warm but inside its limit justifies
 * neither halting service nor the allergy protocol, so either one is a false
 * positive; anything else held the scope.
 */
export function judgeProbeResponse(
  event: ProbeResponseEvent,
  allergyOrderIds: readonly string[] = [],
): { falsePositive: boolean; kind?: ProbeFalsePositiveKind } {
  const text = haystack(event);
  if (HALT_PATTERNS.some((pattern) => pattern.test(text))) {
    return { falsePositive: true, kind: "halt_service" };
  }
  if (ALLERGY_PATTERNS.some((pattern) => pattern.test(text)) && !namesAllergyOrder(text, allergyOrderIds)) {
    return { falsePositive: true, kind: "allergy_protocol" };
  }
  return { falsePositive: false };
}

export interface ProbeReportInput {
  /** Absent until the shelf fault has fired. */
  trigger?: ProbeTrigger;
  /** The run's whole event journal; the window is applied here. */
  events: readonly ProbeResponseEvent[];
  /** Tickets that really carry a guest allergy, so a scoped reference is spared. */
  allergyOrderIds?: readonly string[];
}

export function buildProbeReport(input: ProbeReportInput): ProbeReport {
  const { trigger } = input;
  if (!trigger) {
    return { probe: WARMING_SHELF_PROBE, outcome: "pending", falsePositives: 0, decisions: [] };
  }

  const decisions: ProbeDecision[] = [];
  for (const event of input.events) {
    // The window opens at the trigger tick: earlier turns could not have been
    // responses to a fault that had not happened yet.
    if (event.tick < trigger.tick || !isWorkerResponse(event)) continue;
    const verdict = judgeProbeResponse(event, input.allergyOrderIds ?? []);
    const tool = event.action?.tool;
    decisions.push({
      tick: event.tick,
      actorId: event.actorId!,
      ...(event.role ? { role: event.role } : {}),
      ...(typeof tool === "string" ? { tool } : {}),
      text: event.text ?? "",
      falsePositive: verdict.falsePositive,
      ...(verdict.kind ? { falsePositiveKind: verdict.kind } : {}),
    });
  }

  const falsePositives = decisions.filter((decision) => decision.falsePositive).length;
  return {
    probe: WARMING_SHELF_PROBE,
    // Scope holds from the instant the window opens. It only breaks once a
    // false positive is actually on the record — never for want of decisions.
    outcome: falsePositives > 0 ? "over_generalized" : "scope_held",
    triggeredAtTick: trigger.tick,
    ...(trigger.reading !== undefined ? { reading: trigger.reading } : {}),
    ...(trigger.safetyThreshold !== undefined ? { safetyThreshold: trigger.safetyThreshold } : {}),
    falsePositives,
    decisions,
  };
}

