// ── Standing corrections ─────────────────────────────────────────────

/**
 * Every correction currently in force, in the order it was issued. A
 * correction leaves this list only when it is explicitly lifted — never
 * because the tick it was issued on has passed.
 */
activeDirectives(): StandingDirective[] {
  return this.directives.active();
}

/**
 * The corrections targeting `role`, in issue order: those still in force,
 * unless `includeLifted` asks for the role's whole history. This is the list
 * the role's own prompt is built from, so what a worker is told it is bound
 * by and what the boundary will actually refuse are the same list.
 */
directivesFor(role: Role | "expediter", options: { includeLifted?: boolean } = {}): StandingDirective[] {
  return this.directives.forRole(role, options);
}

/** Everything issued this shift, lifted included, in issue order. */
directiveHistory(): StandingDirective[] {
  return this.directives.all();
}

/** The live allergy ticket a substitution correction is about, if there is one. */
private liveAllergyOrderId(): string | undefined {
  return this.currentState.orders.find((order) => order.allergy && ACTIVE_ORDER_STATUSES.has(order.status))?.id;
}

/**
 * "Verify before substituting", held. Scoped to the live allergy ticket when
 * there is one — a correction about table 2's peanut plate has no business
 * governing table 1's pasta — and unscoped otherwise, which covers every
 * ticket rather than none.
 */
private issueVerifyDirective(note: string, targetRole?: Role): StandingDirective {
  // The pass is where a swap happens, so both its roles carry the rule even
  // when the manager said it to one of them.
  const roles: Role[] = ["chef", "supply_lead"];
  if (targetRole && !roles.includes(targetRole)) roles.push(targetRole);
  const orderId = this.liveAllergyOrderId();
  return this.directives.issue({
    category: "safety",
    rule: "verify_before_substituting",
    note,
    roles,
    tick: this.currentState.episode.tick,
    ...(orderId ? { orderId } : {}),
  });
}

/** The named ticket keeps its place at the front of the pass until lifted. */
private issueTicketPriorityDirective(orderId: string, note: string): StandingDirective {
  return this.directives.issue({
    category: "priority",
    rule: "ticket_priority",
    note,
    roles: ["chef", "supply_lead"],
    tick: this.currentState.episode.tick,
    orderId,
  });
}

/** A held door binds the two roles that can put a party at a table. */
private issueHoldDoorDirective(note: string): StandingDirective {
  return this.directives.issue({
    category: "pace",
    rule: "hold_the_door",
    note,
    roles: ["host", "server"],
    tick: this.currentState.episode.tick,
  });
}

/** The door reopened, so the correction that closed it stops binding. */
private liftHoldDoorDirectives(): void {
  this.directives.liftMatching((directive) => directive.rule === "hold_the_door", this.currentState.episode.tick);
}

/** Words a relay is likely to use for a correction of each category. */
private static readonly CATEGORY_WORDS: Readonly<Record<DirectiveCategory, readonly string[]>> = {
  safety: ["safety", "allerg", "verify", "verified", "unverified"],
  priority: ["priority", "prioritis", "prioritiz"],
  quality: ["quality"],
  pace: ["pace", "pacing", "hold the door", "holding the door", "door is held", "seating held"],
};

/**
 * Credit the worker for the correction it just carried out.
 *
 * `correctionUptake` belongs to the body that did the thing the correction
 * asked for — verified the swap, kept the door shut. `coordination` is the
 * separate claim that a correction was *moved along*: re-timing the ticket a
 * correction named earns both, while relaying one to the next station earns
 * only coordination, because nothing has been carried out yet. Each credit
 * is one-off per directive and worker, so repeating the same move on later
 * turns cannot ratchet an outcome upwards.
 */
private creditDirectiveWork(envelope: ActionEnvelope): void {
  if (envelope.actorType !== "worker") return;
  const out = this.currentState.outcomes;
  const creditUptake = (directive: StandingDirective): void => {
    if (!this.directives.claimCredit(directive.id, envelope.actorId, "carried_out")) return;
    out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
  };
  const creditCoordination = (directive: StandingDirective, amount: number): void => {
    if (!this.directives.claimCredit(directive.id, envelope.actorId, "moved_along")) return;
    out.coordination = Math.min(1, out.coordination + amount);
  };

  if (envelope.tool === "coordinate") {
    const orderId = envelope.arguments.orderId;
    if (typeof orderId !== "string") return;
    // Re-timing the ticket a priority correction named is both carrying it
    // out and keeping it moving through the pass.
    const named = this.directives
      .activeByRule("ticket_priority")
      .find((directive) => directiveCoversOrder(directive, orderId));
    if (!named) return;
    creditUptake(named);
    creditCoordination(named, 0.5);
    return;
  }

  if (envelope.tool === "prepare") {
    const orderId = envelope.arguments.orderId;
    const verified = envelope.arguments.verified === true || envelope.arguments.verifiedSafe === true;
    if (!verified || typeof orderId !== "string") return;
    const covering = this.directives
      .activeByRule("verify_before_substituting")
      .find((directive) => directiveCoversOrder(directive, orderId));
    if (covering) creditUptake(covering);
    return;
  }

  if (envelope.tool === "update_guest") {
    // Quoting the room an honest wait instead of seating into it is what
    // holding the door actually looks like from the floor.
    const hold = this.directives
      .activeByRule("hold_the_door")
      .find((directive) => directive.roles.includes(envelope.role));
    if (hold) creditUptake(hold);
    return;
  }

  if (envelope.tool === "send_message") {
    const text = typeof envelope.arguments.text === "string" ? envelope.arguments.text.toLowerCase() : "";
    if (!text) return;
    for (const directive of this.directives.active()) {
      const words = RestaurantGame.CATEGORY_WORDS[directive.category];
      if (words.some((word) => text.includes(word))) {
        creditCoordination(directive, 0.25);
        return;
      }
    }
  }
}

/**
 * The warming-shelf scope probe: what the workers did once the shelf started
 * running warm while staying inside its safety limit. `pending` until that
 * fires, then `scope_held` unless somebody treated an operational fault as a
 * food-safety emergency.
 */
probeReport(): ProbeReport {
  return buildProbeReport({
    ...(this.shelfProbe ? { trigger: this.shelfProbe } : {}),
    events: this.eventJournal,
    // Naming a ticket that really carries an allergy is a worker doing its
    // job, not the protocol being over-applied to a warm shelf.
    allergyOrderIds: this.currentState.orders.filter((order) => order.allergy).map((order) => order.id),
  });
}

