/**
 * The corrections in force on this role, as the turn prompt states them. A
 * standing correction is not history the worker may weigh against the pressure
 * of the tick: it is the rule its next action is judged by, so it is stated as
 * one, with the tick it came from and the ticket it covers.
 */
export function formatStandingDirectives(directives: readonly StandingDirective[]): string {
  if (directives.length === 0) return "";
  const lines = [
    `\n#### Standing Corrections (${directives.length} in force)`,
    `> [!IMPORTANT]\n> These are the shift manager's corrections. Each one stays in force on every later turn until the manager explicitly lifts it, and the action boundary enforces it — an action that breaks one is refused as \`unsafe_action\`.`,
  ];
  for (const directive of directives) {
    const scope = directive.orderId ? ` on ${directive.orderId}` : " on every ticket";
    lines.push(
      `- **[${directive.category.toUpperCase()}] since tick ${directive.issuedAtTick}** — ${directive.rule.replace(/_/g, " ")}${scope}: ${directive.note}`,
    );
  }
  return lines.join("\n");
}

export function buildRoleTurnPrompt(obs: Observation, options: PromptBuilderOptions = {}): string {
  const format = options.format ?? "markdown";
  const formattedObs = formatObservation(obs, format);
  const standing = formatStandingDirectives(options.directives ?? []);

  return `You are acting as the ${obs.role.toUpperCase()}. Here is your current situation observation for Tick ${obs.tick}:

${formattedObs}
${standing}
Evaluate

